    methodologyBody:
      "픽업 속도는 FUZE 랩 수직 패더(HTAI P-B0, 41 cm 롤러 둘레)에서 AATCC / ASTM 패드 적용 방법에 따라 측정됨 — 원단은 4 bar로 압착된 두 패드 사이의 저장조에 보관된 욕조를 통해 위쪽으로 통과합니다. 샘플은 FUZE 커터에서 100 cm²로 절단, 20–25 °C에서 컨디셔닝. 건조-습윤 실행: 건조 샘플을 깨끗한 DI 물에 10초 침지, 3초 배수, {p} bar / {hz} Hz(단일 패스)에서 패딩, 10초 이내 무게 측정. 측정은 3회 수행; 보고된 픽업은 산술 평균. 벤치 테스트 욕조는 30 mg/L FUZE 스톡에서 목표 단계 농도로 준비되고 ICP 검증을 위해 동일한 저장조를 통해 패드 적용됨. 희석 레시피는 FUZE 스톡 농도 {stock} mg/L 및 단계 OWF 목표(F1 1.0 mg/kg · F2 0.75 mg/kg · F3 0.5 mg/kg · F4 0.25 mg/kg)를 사용하여 픽업 평균에서 도출.",
