    sevenRulesLabel: "일곱 가지 규칙",
    rule1: "ICP 우선. 어떤 항균 시험도 mg/kg 단위의 원단 로딩에 대한 ICP 확인 없이 시작되지 않습니다.",
    rule2: "살균은 UV 전용. 120°C 오토클레이브는 나일론, 폴리에스터 및 합성 혼방을 손상시키며 — 시험을 망칩니다.",
